-- Can You Finish All Courses? (Medium)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$course-schedule$q$, $q$Can You Finish All Courses?$q$, $q$There are n courses numbered 1 to n. Each requirement "a b" means course a must be completed before course b can be started. You take one course at a time.

Decide whether it is possible to complete every course.$q$, $q$Medium$q$, $q$Graphs$q$, 'code', ARRAY[$q$graph$q$, $q$topological-sort$q$, $q$cycle-detection$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n and m.\n    # Next m lines: two integers a and b.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n and m.\n// Next m lines: two integers a and b.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n and m.\n        // Next m lines: two integers a and b.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n and m.\n    // Next m lines: two integers a and b.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n and m.\n    // Next m lines: two integers a and b.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "4 3\n1 2\n2 3\n3 4", "output": "YES", "explanation": "Take 1, 2, 3, 4 in order."}, {"input": "2 2\n1 2\n2 1", "output": "NO", "explanation": "Each course waits for the other."}]$q$::jsonb, ARRAY[$q$1 ≤ n ≤ 10 000$q$, $q$0 ≤ m ≤ 20 000$q$, $q$1 ≤ a, b ≤ n; duplicate requirements and a = b may occur$q$]::text[], 25, 1015, 2000, 262144, $q$Line 1: n and m.
Next m lines: two integers a and b.$q$, $q$YES if all courses can be completed, otherwise NO.$q$, $q$This is cycle detection in a directed graph. Kahn's algorithm: compute in-degrees, repeatedly take a course with in-degree 0, and lower the in-degree of its successors. If every course gets taken the answer is YES; if some are never freed, they sit on a cycle. A self-requirement a = a is a cycle of length 1. O(n + m).$q$, false)
ON CONFLICT (slug) DO NOTHING;

